//! Wire types for the Acpilot API.
//!
//! This crate is the contract between `acpilotd` and every client (CLI, TUI, GUI,
//! web). It contains no logic and no I/O: only types that round-trip through
//! JSON, plus the generated OpenAPI document. Domain types live in
//! `acpilot-core`; if a type is not reachable from a request or a response, it
//! does not belong here.
//!
//! Identifiers are opaque strings on the wire on purpose: they are generated by
//! the daemon and may change representation. Timestamps are RFC 3339 strings for
//! the same reason — the wire format should not track a library choice.

pub mod agent;
pub mod bridge;
pub mod error;
pub mod event;
pub mod extension;
pub mod file;
pub mod host;
pub mod lsp;
pub mod model;
pub mod permission;
pub mod profile;
pub mod session;
pub mod stats;
pub mod terminal;
pub mod workspace;

pub use error::{ErrorBody, ErrorDetail};

use utoipa::OpenApi;

/// Version prefix for every route in the v1 surface.
pub const API_PREFIX: &str = "/v1";

/// The OpenAPI document for the whole API.
///
/// Schemas are registered here as they are added; paths are registered once the
/// daemon grows endpoints (P3). A snapshot test in this crate fails when the
/// document changes, so a wire change is always visible in review.
#[derive(OpenApi)]
#[openapi(
    info(
        title = "Acpilot API",
        description = "Control plane for editing and ACP agents. Clients observe state and \
                       submit intent; file contents never round-trip through this API on the \
                       keystroke path.",
        version = "0.1.0",
        license(name = "MIT OR Apache-2.0")
    ),
    components(schemas(
        error::ErrorBody,
        error::ErrorDetail,
        host::HostKind,
        host::HostSummary,
        host::HostCapabilities,
        workspace::WorkspaceSummary,
        workspace::WorkspaceOpenRequest,
        agent::AgentTransport,
        agent::AgentSummary,
        agent::AgentStatus,
        session::SessionSummary,
        session::SessionStatus,
        session::CreateSessionRequest,
        session::PromptRequest,
        session::PromptAccepted,
        event::SessionEvent,
        event::SessionEventKind,
        permission::PermissionKind,
        permission::PermissionOption,
        permission::PermissionDecision,
        permission::PermissionRequest,
        file::FileEntry,
        file::FileContent,
        file::FileWriteRequest,
        terminal::TerminalSize,
        terminal::TerminalSummary,
        profile::ProfileSummary,
        profile::Preferences,
        lsp::LspServerSummary,
        lsp::LspServerStatus,
        lsp::PositionEncoding,
        model::ProviderKind,
        model::ProviderStatus,
        model::MetadataSource,
        model::ModelCapabilities,
        model::ModelType,
        model::ProviderSummary,
        model::AddProviderRequest,
        model::DiscoveredModel,
        model::SamplingParams,
        model::ContextStrategy,
        model::ContextBudget,
        model::ToolExposure,
        model::ModelRecipe,
        model::CorpusSelector,
        model::RunRequest,
        model::RunStatus,
        model::TokenUsage,
        model::RunSummary,
        model::PromoteRecipeRequest,
        model::PromotedAgent,
        stats::IntegrationKind,
        stats::StatSource,
        stats::ContextStats,
        stats::CreditStats,
        stats::IntegrationStats,
        bridge::DriverScope,
        bridge::BridgeTransport,
        bridge::DriverStatus,
        bridge::AcpBridgeSummary,
        bridge::AcpDriverSummary,
        bridge::PairingCode,
        bridge::PairDriverRequest,
        extension::ExtensionKind,
        extension::ExtensionSource,
        extension::ExtensionStatus,
        extension::ExtensionSummary,
        extension::ExtensionContribution,
        extension::ExtensionDetail,
        extension::InstallExtensionRequest,
        extension::ThemeAppearance,
        extension::ThemeSummary
    ))
)]
pub struct ApiDoc;

/// Render the OpenAPI document as pretty JSON.
///
/// Used by the daemon's `/v1/openapi.json` route and by the snapshot test. The
/// document is built from types at compile time, so serialisation cannot fail in
/// practice; a panic here is a programming error, not a runtime condition.
#[must_use]
pub fn openapi_json() -> String {
    serde_json::to_string_pretty(&ApiDoc::openapi())
        .expect("the generated OpenAPI document is always serialisable")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn document_parses_as_json() {
        let json = openapi_json();
        let value: serde_json::Value = serde_json::from_str(&json).expect("valid JSON");
        assert_eq!(value["openapi"], "3.1.0");
        assert_eq!(value["info"]["title"], "Acpilot API");
    }

    #[test]
    fn every_module_schema_is_registered() {
        let doc = ApiDoc::openapi();
        let schemas = doc.components.expect("components are registered").schemas;
        for name in [
            "ErrorBody",
            "WorkspaceSummary",
            "SessionEvent",
            "PermissionRequest",
            "Preferences",
            "ModelRecipe",
            "RunSummary",
            "IntegrationStats",
            "AcpBridgeSummary",
            "AcpDriverSummary",
            "ExtensionSummary",
            "ThemeSummary",
        ] {
            assert!(schemas.contains_key(name), "{name} missing from components");
        }
    }
}
